-- OutLawed India Seeding Data
-- Execute this script inside MySQL Workbench to populate the tables

USE outlawed_db;

-- 1. Seed Demo Users
ON DUPLICATE KEY UPDATE name=VALUES(name), role=VALUES(role);

-- 2. Seed Initial Case Records (explicit IDs matching React frontend)
ON DUPLICATE KEY UPDATE status=VALUES(status), situation=VALUES(situation);

-- 3. Seed Case Tasks Checklist
ON DUPLICATE KEY UPDATE done=VALUES(done);

-- 4. Seed Case Notes
ON DUPLICATE KEY UPDATE text=VALUES(text);

-- 5. Seed 50 Anonymized Previously Resolved Cases
ON DUPLICATE KEY UPDATE title=VALUES(title), problem=VALUES(problem);
